  description: '这一条意见的标题、详细说明与使用场景都合法，拒绝结果只能来自无法读取已有数据。',
  scenario: '需要先恢复历史意见数据的场景',
};

function freshDir(): string {
  return mkdtempSync(join(tmpdir(), 'featureharbor-corrupt-'));
}

